/**
 * Unit tests for MathArrays.linearCombination.
 */
public class MathArrays_linearCombination_TriageGen5Test {

    private static final double DELTA = 1e-12;











    @Test
    public void testLinearCombination_WithNaN() throws DimensionMismatchException {
        // This triggers the 'if (Double.isNaN(result))' branch
        double[] a = {Double.NaN, 1.0};
        double[] b = {1.0, 1.0};
        // The fallback loop: NaN*1 + 1*1 = NaN. 
        // But the fallback loop calculates: result += a[i]*b[i].
        // If a[0] is NaN, result becomes NaN. 
        // Wait, the fallback loop: result = 0; result += NaN*1 -> result is NaN.
        // However, if we use a value that results in NaN through overflow/split:
        double[] a2 = {Double.POSITIVE_INFINITY, 1.0};
        double[] b2 = {1.0, 1.0};
        // Infinity * 1 = Infinity. Not NaN.

        // To trigger the NaN branch specifically:
        double[] a3 = {Double.NaN, 2.0};
        double[] b3 = {2.0, 2.0};
        // result will be NaN, then the fallback loop runs:
        // result = 0; result += NaN * 2.0 (NaN); result += 2.0 * 2.0 (NaN).
        // Actually, if any element is NaN, the fallback results in NaN.
        // The only way the fallback loop returns a non-NaN is if the math errors 
        // in the complex split logic but the naive loop avoids it (rare in IEEE754).
        // Let's test with a NaN to ensure we hit the branch.
        double res = MathArrays.linearCombination(a3, b3);
        assertEquals(Double.NaN, res, 0.0);
    }






}

